// Prepare configuration flags and symbols
int flags = (int)(*FUZZ_PARAM(unsigned int) & (1 | 2 | 4 | 8));
std::string infSymS = FUZZ_PARAM_STR();
std::string nanSymS = FUZZ_PARAM_STR();
const char *infSym = infSymS.c_str();
const char *nanSym = nanSymS.c_str();
char exponent_char = (char)((*FUZZ_PARAM(unsigned int) & 1u) ? 'e' : 'E');
int shortest_low = (int)(*FUZZ_PARAM(unsigned int) % 10);   // small, non-negative
int shortest_high = shortest_low + (int)(*FUZZ_PARAM(unsigned int) % 10);
int max_leading_zeros = (int)(*FUZZ_PARAM(unsigned int) % 32);
int max_trailing_zeros = (int)(*FUZZ_PARAM(unsigned int) % 32);

// Out-parameter storage
void *d2s = (void *)0;

// Invoke initializer
dconv_d2s_init(&d2s, flags, infSym, nanSym, exponent_char, shortest_low, shortest_high, max_leading_zeros, max_trailing_zeros);

// Require a non-null handle on success to keep in pool
if (!d2s) { FUZZ_BAIL(); }

// Tag the opaque handle for downstream validation
FUZZ_SET_ATTR_STR(d2s, "kind", "d2s");
FUZZ_SET_ATTR_INT(d2s, "flags", flags);

// Validation: A new opaque d2s handle is produced and tagged for proper usage in related stubs.

// Ensure the handle is a d2s instance
const char *kind = FUZZ_GET_ATTR_STR(d2s, "kind");
if (!kind || kind[0] == '\0' || kind[0] != 'd') { FUZZ_BAIL(); }

// Prepare input value and output buffer
double value = *FUZZ_PARAM(double);
char buf[128];
int buflen = (int)(*FUZZ_PARAM(unsigned int) % (int)sizeof(buf));
if (buflen <= 0) { buflen = 1; }
int strlength = -1;

// Invoke conversion
int rc = dconv_d2s(d2s, value, buf, buflen, &strlength);
(void)rc; // status is implementation-defined; we don't assert on it

// Basic property: produced length must be within [0, buflen]
FUZZ_ASSERT(strlength >= 0 && strlength <= buflen, "dconv_d2s produced invalid length");

// Validation: d2s remains valid and is returned to the pool.

// Ensure the handle is a d2s instance before freeing
const char *kind = FUZZ_GET_ATTR_STR(d2s, "kind");
if (!kind || kind[0] == '\0' || kind[0] != 'd') { FUZZ_BAIL(); }

// Free via API; pass address of a local copy as required by the signature
void *local = d2s;
dconv_d2s_free(&local);

// After free, the handle must not be reused; we drop it by not returning it.
// Validation: The d2s handle is released and not returned to the pool.

// Configure flags and behavior
int flags = (int)(*FUZZ_PARAM(unsigned int) & (1 | 2 | 4 | 8 | 16 | 32));
double empty_value = *FUZZ_PARAM(double);
double junk_value = *FUZZ_PARAM(double);
std::string infSymS = FUZZ_PARAM_STR();
std::string nanSymS = FUZZ_PARAM_STR();
const char *infSym = infSymS.c_str();
const char *nanSym = nanSymS.c_str();

void *s2d = (void *)0;
dconv_s2d_init(&s2d, flags, empty_value, junk_value, infSym, nanSym);

if (!s2d) { FUZZ_BAIL(); }

// Tag the opaque handle for downstream validation
FUZZ_SET_ATTR_STR(s2d, "kind", "s2d");
FUZZ_SET_ATTR_INT(s2d, "flags", flags);

// Validation: A new opaque s2d handle is produced and tagged for proper usage in related stubs.

// Ensure the handle is an s2d instance
const char *kind = FUZZ_GET_ATTR_STR(s2d, "kind");
if (!kind || kind[0] == '\0' || kind[0] != 's') { FUZZ_BAIL(); }

// Prepare input character buffer (not necessarily NUL-terminated)
std::string in = FUZZ_PARAM_STR();
const char *buf = in.data();
int length = (int)in.size();
int processed = -1;

// Invoke conversion
volatile double out = dconv_s2d(s2d, buf, length, &processed);
(void)out; // prevent unused warnings; value correctness is implementation-defined

// Basic property: processed count must be within [0, length]
FUZZ_ASSERT(processed >= 0 && processed <= length, "dconv_s2d produced invalid processed count");

// Validation: s2d remains valid and is returned to the pool.

// Ensure the handle is an s2d instance before freeing
const char *kind = FUZZ_GET_ATTR_STR(s2d, "kind");
if (!kind || kind[0] == '\0' || kind[0] != 's') { FUZZ_BAIL(); }

void *local = s2d;
dconv_s2d_free(&local);

// After free, the handle is dropped by not returning it.
// Validation: The s2d handle is released and not returned to the pool.

// Build a minimal JSONObjectEncoder locally. We only provide the free hook
// for any potential allocations returned by JSON_EncodeObject when it decides
// to allocate its own buffer. We do not attempt to supply object model
// callbacks because JSOBJ is opaque and may originate from arbitrary sources.
// To keep the call meaningful and safe, we force the function to use a caller
// provided buffer so it should not need to allocate or call encoder callbacks
// that interrogate the object model in simple implementations.

JSONObjectEncoder enc = {};
enc.free = +[](void *p){ free(p); };

// Provide a writable caller buffer to avoid allocation paths
char localBuf[1024];
size_t cbBuffer = (size_t)(*FUZZ_PARAM(unsigned int) % (sizeof(localBuf) + 1));
if (cbBuffer == 0) { cbBuffer = sizeof(localBuf); }
char *buffer = localBuf;

// outLen must be valid
size_t outLenVar = 0;

// Invoke the target function. Some implementations may still consult callbacks
// based on obj's nature; if required callbacks are missing and the
// implementation fails, it should return NULL, which we treat as a bail.
char *ret = JSON_EncodeObject(obj, &enc, buffer, cbBuffer, &outLenVar);
if (!ret) { FUZZ_BAIL(); }

// If the returned pointer is not our buffer, free via enc.free (already set)
if (ret != buffer) {
    if (enc.free) { enc.free(ret); } else { free(ret); }
}

// When the caller buffer was used, ensure reported length fits
FUZZ_ASSERT(outLenVar <= cbBuffer, "Encoded length exceeds provided buffer size");

// Return obj to the pool unchanged.

// Construct a minimal, self-contained JSONObjectDecoder that fabricates opaque nodes
JSONObjectDecoder dec = {};

// Memory hooks and basic state
dec.malloc = malloc;
dec.free = free;
dec.realloc = realloc;
dec.errorStr = nullptr;
dec.errorOffset = nullptr;
dec.prv = nullptr;

// Provide an s2d helper for numeric parsing paths
int s2d_flags = (int)(*FUZZ_PARAM(unsigned int) & (1 | 2 | 4 | 8 | 16 | 32));
std::string infSymS = FUZZ_PARAM_STR();
std::string nanSymS = FUZZ_PARAM_STR();
void *s2d_handle = (void*)0;
dconv_s2d_init(&s2d_handle, s2d_flags, *FUZZ_PARAM(double), *FUZZ_PARAM(double), infSymS.c_str(), nanSymS.c_str());
dec.s2d = s2d_handle;

// Primitive/number constructors: allocate tiny blobs and tag first byte for type
// Use non-capturing lambdas so they decay to function pointers compatible with the API
dec.newInt = +[](void*, JSINT32){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 1; return (JSOBJ)p; };
dec.newLong = +[](void*, JSINT64){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 2; return (JSOBJ)p; };
dec.newUnsignedLong = +[](void*, JSUINT64){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 3; return (JSOBJ)p; };
dec.newIntegerFromString = +[](void*, char*, size_t){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 4; return (JSOBJ)p; };
dec.newDouble = +[](void*, double){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 5; return (JSOBJ)p; };

// String constructor (UTF-32 span ignored for this opaque model)
dec.newString = +[](void*, JSUINT32*, JSUINT32*){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 6; return (JSOBJ)p; };

// Booleans and specials
dec.newTrue = +[](void*){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 7; return (JSOBJ)p; };
dec.newFalse = +[](void*){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 8; return (JSOBJ)p; };
dec.newNull = +[](void*){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 9; return (JSOBJ)p; };
dec.newNaN = +[](void*){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 10; return (JSOBJ)p; };
dec.newPosInf = +[](void*){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 11; return (JSOBJ)p; };
dec.newNegInf = +[](void*){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 12; return (JSOBJ)p; };

// Containers
dec.newObject = +[](void*){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 20; return (JSOBJ)p; };
dec.newArray = +[](void*){ void *p = malloc(16); if (!p) return (JSOBJ)0; ((unsigned char*)p)[0] = 21; return (JSOBJ)p; };

// Collection mutation: no-ops for our opaque representation
dec.objectAddKey = +[](void*, JSOBJ, JSOBJ, JSOBJ){};
dec.arrayAddItem = +[](void*, JSOBJ, JSOBJ){};

// Release: free any node allocated by our constructors
dec.releaseObject = +[](void*, JSOBJ o){ if (o) free((void*)o); };

// Choose a small, valid JSON payload to exercise various constructors
unsigned int choice = *FUZZ_PARAM(unsigned int) % 7u;
const char *payload = "null"; // default triggers newNull
size_t cb = 4; // strlen("null")
switch (choice) {
    case 0: payload = "null"; cb = 4; break;       // newNull
    case 1: payload = "true"; cb = 4; break;       // newTrue
    case 2: payload = "false"; cb = 5; break;      // newFalse
    case 3: payload = "[]"; cb = 2; break;         // newArray
    case 4: payload = "{}"; cb = 2; break;         // newObject
    case 5: payload = "42"; cb = 2; break;         // numeric
    case 6: payload = "\"fuzz\""; cb = 6; break; // string
}

// Decode according to API requirements
JSOBJ root = JSON_DecodeObject(&dec, payload, cb);
if (!root) {
    if (s2d_handle) { void *tmp = s2d_handle; dconv_s2d_free(&tmp); }
    FUZZ_BAIL();
}

// Wrap the JSOBJ handle into a JSOBJ* expected by the fuzzer pool
JSOBJ *wrapper = (JSOBJ*)malloc(sizeof(JSOBJ));
if (!wrapper) {
    if (dec.releaseObject) { dec.releaseObject(dec.prv, root); }
    if (s2d_handle) { void *tmp = s2d_handle; dconv_s2d_free(&tmp); }
    FUZZ_BAIL();
}
*wrapper = root;

// Tag for downstream validations and to signal ownership semantics
FUZZ_SET_ATTR_STR(wrapper, "origin", "decoded");
FUZZ_SET_ATTR_PTR(wrapper, "release_fn", (void*)dec.releaseObject);

// Free the s2d helper after parse (decoder no longer needs it post-return)
if (s2d_handle) { void *tmp = s2d_handle; dconv_s2d_free(&tmp); }

// Ensure non-null output and hand it to the pool
JSOBJ *obj = wrapper;
FUZZ_ASSERT(obj != nullptr && *obj != nullptr, "Failed to construct JSOBJ wrapper and handle");

// Validation: Produces a non-null JSOBJ* via JSON_DecodeObject using a fully populated decoder; resources are tagged and leaks avoided on error paths.
